fragment.set-body:
@{
    var body = context.Request.Body.As<JObject>(preserveContent: true) ?? new JObject();
    body.Remove("model");
    body["agent_reference"] = new JObject(
      new JProperty("type", "agent_reference"),
      new JProperty("name", context.Variables.GetValueOrDefault<string>("agent-name")),
      new JProperty("version", context.Variables.GetValueOrDefault<string>("agent-version")));
    return body.ToString();
  }
